"""Complete 24 original abdominal-examination questions."""
from create_exam_abdominal_organs import rows,q,AB,SP,AS,ref
from qbank_authoring import finalize

q('Abdominal muscle tension reduces with distraction, warm hands and slow breathing. Which interpretation is favored?', 'A voluntary guarding component rather than fixed involuntary rigidity',[
 ('Definite absence of all intra-abdominal pathology','Voluntary guarding can coexist with real painful disease.'),('A fixed board-like peritoneal response established by any tension','The response to relaxation suggests a voluntary component.'),('A diagnosis of functional pain solely from relaxation','This does not establish a psychiatric or functional cause.')],
 'Improve comfort before interpreting resistance','**Anxiety, cold and anticipated pain can tense the abdominal wall.**',['True involuntary rigidity is less readily relaxed.','Terminology varies, so describe the observed behavior clearly.'],'**Continue a gentle cause-directed examination.**',['Start away from the painful site.','Do not dismiss pain because some tension relaxes.'],[['Voluntary component','Changes with relaxation'],['Involuntary rigidity','Persistent protective response'],['Clinical meaning','Needs context']],[AB],style='clinical_scenario')

q('A patient has severe localized abdominal pain and pain with light percussion or coughing. Which approach is appropriate?', 'Recognize possible peritoneal irritation without repeatedly provoking forceful rebound tenderness',[
 ('Repeat painful rebound testing until the patient cannot tolerate it','This adds distress without necessarily adding useful information.'),('Exclude peritoneal irritation unless rebound has been elicited many times','Other signs can support the assessment.'),('Withhold all analgesia because examination must remain painful','Appropriate analgesia should not be denied.')],
 'A diagnostic examination should minimize unnecessary harm','**Movement-related pain can support peritoneal irritation.**',['Interpret location and associated systemic signs.','The sign does not identify the underlying cause by itself.'],'**Provide analgesia and arrange timely investigation/surgical assessment as indicated.**',['Reassess after treatment.','Do not delay care to complete every traditional maneuver.'],[['Clue','Pain with movement/percussion'],['Avoid','Repeated forceful provocation'],['Action','Cause evaluation and comfort']],[AB],style='clinical_scenario')

q('Palpation beneath the right costal margin causes pain and abrupt inspiratory arrest as the patient breathes in. Which sign is described?', 'Murphy sign',[
 ('Psoas sign','This uses hip movement to stress the psoas region.'),('Carnett sign','This compares tenderness during abdominal-wall tensing.'),('Rovsing sign','This refers to right-sided pain elicited by left-sided abdominal pressure in the appropriate context.')],
 'A moving inflamed gallbladder region can interrupt inspiration','**Murphy sign supports acute gallbladder inflammation in the right clinical setting.**',['Its absence does not reliably exclude disease, particularly in some older or atypical patients.','Other causes of right upper-quadrant pain remain possible.'],'**Use ultrasound and the complete inflammatory/clinical picture.**',['Assess cholangitis, obstruction and other urgent alternatives.','Do not equate one sign with a definitive diagnosis.'],[['Maneuver','Right subcostal palpation/inspiration'],['Positive','Pain-related arrest'],['Interpretation','Supports, does not prove cholecystitis']],[AB],style='clinical_scenario')

q('Extension of the right hip worsens right lower-quadrant pain. Which anatomical relationship may explain a positive psoas sign?', 'Inflammation adjacent to the iliopsoas, including a retrocecal appendix',[
 ('A specific proof of gallbladder obstruction','The maneuver stresses a different region.'),('A direct test of the rectus sheath alone','Hip extension stretches the iliopsoas.'),('A guarantee that the appendix is normal if the sign is absent','Sensitivity is insufficient to exclude appendicitis.')],
 'Provocation tests localize contact with an anatomical structure','**Stretching an irritated psoas region can reproduce pain.**',['Several retroperitoneal/inflammatory processes can produce the response.','It is not uniquely diagnostic of appendicitis.'],'**Integrate the sign with history, examination and appropriate imaging.**',['Avoid excessive painful repetition.','Assess for alternative pelvic, urinary and GI causes.'],[['Structure','Iliopsoas'],['Possible cause','Retrocecal appendiceal inflammation'],['Limit','Not sensitive/specific enough alone']],[AB])

q('A jaundiced patient has a palpable nontender gallbladder and progressive weight loss. Which implication is appropriate?', 'Consider malignant distal biliary obstruction, recognizing that the finding is a clue rather than an absolute rule',[
 ('Gallstones are impossible','Exceptions to the classic Courvoisier association occur.'),('The exact primary malignancy is established by palpation','Imaging and tissue assessment may be required.'),('All obstructive jaundice must produce a palpable gallbladder','Anatomy, chronic inflammation and obstruction level vary.')],
 'A distensible gallbladder reflects the obstruction context','**Painless enlargement can support a gradual distal obstruction.**',['Pancreatic and other periampullary causes are important.','Prior scarring or different anatomy can change the sign.'],'**Investigate jaundice promptly with appropriate imaging.**',['Assess cholangitis and clinical stability.','Do not use the eponym as a substitute for defining the obstruction.'],[['Finding','Nontender palpable gallbladder'],['Concern','Distal malignant obstruction'],['Limit','Not an absolute etiological rule']],[AB],style='clinical_scenario')

q('A midline abdominal mass has expansile pulsation, pushing the examiner’s hands apart. Which next step is appropriate?', 'Assess urgently for an abdominal aortic aneurysm, especially if pain or instability is present',[
 ('Assume every transmitted pulse in a thin person is an aneurysm','Transmitted movement can occur; expansion and the full context matter.'),('Use repeated deep palpation as the definitive exclusion test','Palpation cannot safely exclude or characterize the lesion.'),('Exclude rupture because a mass is not always easy to feel','The classic findings can be absent.')],
 'Distinguish expansile from merely transmitted movement','**Aortic enlargement is a vascular question requiring imaging and clinical urgency assessment.**',['Pain, hypotension and collapse raise emergency concern.','Body habitus limits palpation sensitivity.'],'**Use the appropriate vascular pathway without delay in a symptomatic unstable patient.**',['Bedside ultrasound can identify an aneurysm but may not settle rupture.','Do not let absence of the full triad create reassurance.'],[['Expansile pulse','Aneurysm concern'],['Symptoms/instability','Emergency urgency'],['Confirmation','Imaging and vascular assessment']],[ref('NICE abdominal aortic aneurysm guideline','https://www.nice.org.uk/guidance/ng156/chapter/Recommendations')],style='clinical_scenario')

q('A small focal abdominal tender spot remains equally painful or becomes more painful when the patient tenses the abdominal muscles. Which sign is positive?', 'Carnett sign supporting an abdominal-wall pain source',[
 ('Murphy sign','This uses right subcostal palpation during inspiration.'),('Shifting dullness','This tests for mobile fluid.'),('A definitive exclusion of all intra-abdominal pathology','A positive Carnett sign is supportive and must be interpreted in context.')],
 'Tensing the wall changes access to deeper structures','**Persistent or increased focal pain can support a wall origin.**',['Nerve entrapment, muscle injury and other wall lesions are possibilities.','Systemic red flags or atypical findings still need investigation.'],'**Use a targeted wall and neurological assessment.**',['Consider imaging or diagnostic local treatment when appropriate.','Do not label the pain imaginary or necessarily psychiatric.'],[['Tensing','Pain persists/increases'],['Supports','Wall source'],['Limit','Not absolute exclusion of visceral disease']],[ref('Carnett: pain and tenderness of the abdominal wall','https://jamanetwork.com/journals/jama/article-abstract/247712')],style='clinical_scenario')

q('A succussion splash is heard several hours after intake in a patient with vomiting and early satiety. Which process should be considered?', 'Retained gastric contents from impaired emptying or outlet obstruction',[
 ('A unique diagnosis of pyloric cancer','Several mechanical and motility causes can retain contents.'),('Free peritoneal fluid as the usual source','A splash reflects mixed fluid/air in a hollow compartment.'),('A normal finding that excludes obstruction regardless of timing','Timing and symptoms determine significance.')],
 'A physical sign may identify retention rather than its cause','**Fluid and gas can create a splash when the stomach is not emptying.**',['Recent intake can make the finding less specific.','Gastroparesis and mechanical obstruction need distinction.'],'**Assess hydration, electrolytes and the anatomical/motility cause.**',['Use imaging/endoscopy according to the presentation.','Do not infer the exact level or etiology from the sound alone.'],[['Finding','Splash'],['Meaning','Possible retained gastric contents'],['Cause','Mechanical or motility differential']],[AB],style='clinical_scenario')

q('A patient with distension, colicky pain and vomiting has audible bowel sounds. Which statement is correct?', 'Audible sounds do not exclude mechanical obstruction or bowel ischemia',[
 ('Any sounds prove a normal bowel','Serious disease can coexist with sounds.'),('Absent sounds uniquely establish paralytic ileus','Auscultation is not sufficiently specific for that conclusion.'),('Sound pitch alone reliably determines whether surgery is needed','Clinical severity and imaging matter.')],
 'Auscultation has limited standalone diagnostic power','**Bowel sounds vary with stage, location and examiner observation.**',['Obstruction can have increased, reduced or changing sounds.','Ischemia and perforation require broader assessment.'],'**Use symptoms, peritoneal signs, physiology and imaging.**',['Do not delay escalation because the abdomen is not silent.','Assess hernias and prior surgery history.'],[['Sounds present','Disease still possible'],['Sounds absent','Nonspecific'],['Decision','Integrated clinical/imaging assessment']],[AB],style='clinical_scenario')

q('A smooth suprapubic midline swelling is dull to percussion and a patient has inability to void. Which bedside confirmation is most appropriate?', 'Bladder ultrasound or bladder scan for urinary retention',[
 ('Assume the swelling must be ascites','A distended bladder has a focal suprapubic pattern.'),('Diagnose a pelvic malignancy solely from the percussion note','Retention is a plausible reversible cause requiring direct assessment.'),('Exclude retention because some urine leaked earlier','Overflow can coexist with a large retained volume.')],
 'A common hollow organ can mimic an abdominal mass','**Urinary retention can produce a palpable dull suprapubic swelling.**',['Pain may be absent in chronic retention.','Assess medications, neurological causes and outlet obstruction.'],'**Confirm and manage the retained volume with an appropriate plan.**',['Monitor renal function and post-obstructive effects when relevant.','Do not perform blind invasive procedures into an unidentified mass.'],[['Site','Suprapubic'],['Symptom','Failure to void/overflow'],['Confirmation','Bladder ultrasound']],[AB],style='clinical_scenario')

q('A patient has flank pain and costovertebral-angle tenderness. Which interpretation is most accurate?', 'A urinary/renal cause is possible, but the sign is not specific enough to establish pyelonephritis alone',[
 ('Tenderness proves bacterial kidney infection without urine or systemic assessment','Stones and nonrenal causes can also be tender.'),('Absence of tenderness excludes every renal disorder','Sensitivity is imperfect.'),('The maneuver measures glomerular filtration directly','It is a pain-provocation sign, not a functional assay.')],
 'Tenderness localizes discomfort rather than identifying the pathogen','**Renal inflammation, obstruction and adjacent musculoskeletal disease are part of the differential.**',['Fever, urine findings and imaging indications refine assessment.','Pregnancy, sepsis and obstruction alter urgency.'],'**Use targeted tests and avoid excessive percussion.**',['Assess systemic instability promptly.','Do not treat a painful maneuver as microbiological confirmation.'],[['Sign','Flank/CVA pain'],['Differential','Renal and nonrenal causes'],['Confirmation','Clinical/urine/imaging context']],[AB])

q('An older immunosuppressed patient has severe new abdominal pain but little rigidity or rebound. Which conclusion is appropriate?', 'Serious intra-abdominal disease remains possible despite muted peritoneal signs',[
 ('A soft abdomen excludes perforation or ischemia','Older or immunosuppressed patients can have less dramatic signs.'),('Pain must be functional because examination is mild','This is unsafe diagnostic closure.'),('Imaging should wait until board-like rigidity appears','That can delay time-sensitive treatment.')],
 'The host response affects the examination','**Classic inflammatory signs can be attenuated.**',['Consider ischemia, perforation, infection and medication effects.','Trend physiology and reassess rather than waiting for a textbook presentation.'],'**Investigate promptly according to risk and severity.**',['Use appropriate surgical/medical input.','Provide analgesia and resuscitation while clarifying the cause.'],[['Host','Older/immunosuppressed'],['Signs','May be muted'],['Action','Risk-based timely evaluation']],[AB],style='clinical_scenario')

if __name__=='__main__':finalize('Clinical Examination',4,'Abdominal Examination','exam-abdominal',rows,24)
